// Build-time only: runs the pinned original lobby portraits (client/lobby-poses.ts animateLobbyPose with the rig-ik and
// fighter-motion limb solves, client/menu-portraits.ts framePortrait and its hat-top measure, client/auditor-halo.ts,
// lobby-poses.ts lobbyChair, the portrait mannequin's colours from client/character-rig.ts) and three r180's primitives,
// and records what Tests/LobbyPoseChecks.cs compares with the C# port (Core/NativeLobbyPoses.cs, Core/NativePortraitRules.cs).
// The expected values are never generated by the C# port.
// Usage: node tools/export_lobby_poses.mjs <source checkout at 05950ea with node_modules>  -> Tests/lobby-pose-parity.json
import fs from 'node:fs';import path from 'node:path';import {fileURLToPath,pathToFileURL} from 'node:url';import {createHash} from 'node:crypto';
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..'),source=path.resolve(process.argv[2]);
const pinned={'src/client/lobby-poses.ts':'55ecaef6e00b3f829a588148de9cdf04e43ab028','src/client/menu-portraits.ts':'d251dab1256000e18caa9efb49cee3df4db28372',
 'src/client/auditor-halo.ts':'13fa46aac967bf126884e6402008f8d9876954cd','src/client/rig-ik.ts':'6de6beb1a6cf8f22eb76397d1f8a1de793bde6a7',
 'src/client/fighter-motion.ts':'1ac093703b4b671cd5da182a51fe80c0cd7c66c8','src/client/character-rig.ts':'5a020f684a9a2a29238769f3e18a61cddf545e20',
 'src/client/cosmetics.ts':'1c2586c79b5020fbc385aa0e4a32951f8ccf9cc5','src/client/weapon-visuals.ts':'913f954df486a8ebb73f46d48363b2d447a04521',
 'src/shared/lobby-presentation.ts':'8a9c9c9577ffeb3617bf387a695d52e99ff37053','src/client/character-animation.ts':'7adee1f45fb45b1cc20245ebf0ae559e6db99870'};
for(const [file,blob] of Object.entries(pinned)){const bytes=fs.readFileSync(path.join(source,file));if(createHash('sha1').update(`blob ${bytes.length}\0`).update(bytes).digest('hex')!==blob)throw Error('Source blob mismatch: '+file);}
const {register}=await import(pathToFileURL(path.join(source,'node_modules/tsx/dist/esm/api/index.mjs')).href);register();
const load=f=>import(pathToFileURL(path.join(source,'src',f)).href);
const T=await import(pathToFileURL(path.join(source,'node_modules/three/build/three.module.js')).href);
const {createCharacterRig}=await load('client/character-rig.ts'),{buildWeapon}=await load('client/weapon-visuals.ts'),{dressRig}=await load('client/cosmetics.ts');
const {animateLobbyPose,lobbyChair}=await load('client/lobby-poses.ts'),{framePortrait}=await load('client/menu-portraits.ts'),{auditorHalo,animateCosmetics}=await load('client/auditor-halo.ts');
const {LOBBY_POSES,lobbyPose}=await load('shared/lobby-presentation.ts'),{WEAPONS}=await load('shared/content.ts'),{HATS}=await load('shared/cosmetics.ts');
const r6=x=>Math.round(x*1e6)/1e6,arr=v=>v.toArray().map(r6);
const BONES=['body','pelvis','spine','chest','neck','head','leftShoulder','leftArm','leftElbow','leftHand','rightShoulder','rightArm','rightElbow','rightHand','leftLeg','leftKnee','leftFoot','leftToe','rightLeg','rightKnee','rightFoot','rightToe'];
const POSES=Object.keys(LOBBY_POSES),TIMES=[0,.41,1.3,2.77,4.2];
// MenuPortraits.actor(): the mannequin without arena glow, the weapon on the right hand socket (the off weapon on the left),
// dressed with the hat; the group .88 up.
function make(spec,hat='none',accent='#ff6b35',body='#e5e7eb'){const r=createCharacterRig(accent,body);r.group.position.y=.88;r.sockets.rightHand.add(r.weapon);r.sockets.leftHand.add(r.offWeapon);buildWeapon(r.weapon,spec);r.offWeapon.clear();if(['daggers','emperor','ansatsuken'].includes(spec))buildWeapon(r.offWeapon,spec,true);dressRig(r,{hat});return r;}
// A menu PlayerView (main.ts menuPlayers) at rest; animateLobbyPose isolates it further (lobbyPlayer).
function view(spec){const w=WEAPONS[spec];return {id:'menu-pilot',name:'Pilot',spec,class:w.class,color:'#ff6b35',hp:100,maxHp:100,pos:{x:0,y:.865,z:0},vel:{x:0,y:0,z:0},yaw:0,pitch:0,grounded:true,reach:w.range,windup:w.windup,attackRate:1,attackIndex:0,lastAttack:-100,lastShot:-100,blockTime:0,guarding:false,reloadTime:0,dashTime:0,waveTime:0,hitStunUntil:0,stats:{},chips:{},ammo:10,cosmetics:{}};}
const held=(r,o)=>{const socket=o.parent;if(socket.quaternion.angleTo(new T.Quaternion())>1e-9)throw Error('rotated hand socket');return {v:o.visible?1:0,b:socket===r.sockets.rightHand?13:socket===r.sockets.leftHand?9:-1,p:arr(socket.position.clone().add(o.position)),q:arr(o.quaternion)};};
const COVERS=['left-elbow-joint','right-elbow-joint','left-knee-joint','right-knee-joint','left-kneecap','right-kneecap'];
const poses=[];
for(const spec of Object.keys(WEAPONS).filter(s=>s!=='siren'))for(const pose of POSES)for(const t of TIMES){
 const r=make(spec);animateLobbyPose(r,view(spec),t,.033,pose);
 poses.push({spec,pose,t,bones:BONES.map(b=>[...arr(r[b].position),...arr(r[b].quaternion)]),euler:BONES.map(b=>arr(r[b].rotation).slice(0,3)),weapon:held(r,r.weapon),off:held(r,r.offWeapon),covers:COVERS.map(n=>{const m=r.group.getObjectByName(n);return [r6(m.rotation.x),r6(m.position.y),r6(m.position.z)];})});
}
// framePortrait for each pose over card aspects and hat tops (0: no hat, the bare-head default).
const frames=[];const camera=new T.OrthographicCamera(-1.3,1.3,1.3,-1.3,.1,30),dir=new T.Vector3();
for(const pose of POSES)for(const aspect of [.42,.6,.75,1,1.4,2.2])for(const top of [0,1.6,1.95,2.4,3.1]){framePortrait(camera,pose,aspect,top);camera.getWorldDirection(dir);frames.push({pose,aspect,top,lrtb:[camera.left,camera.right,camera.top,camera.bottom].map(r6),near:camera.near,far:camera.far,position:arr(camera.position),forward:arr(dir)});}
// menu-portraits.ts hatTop(): Box3.setFromObject(head cosmetic socket).max.y in world space (0 when empty).
const hatTops=[];const box=new T.Box3();
for(const hat of Object.keys(HATS))for(const pose of POSES)for(const t of [0,1.3]){const r=make('pistol',hat);animateLobbyPose(r,view('pistol'),t,.033,pose);r.group.updateMatrixWorld(true);box.setFromObject(r.sockets.head);hatTops.push({hat,pose,t,top:box.isEmpty()?0:r6(box.max.y)});}
// The portrait mannequin's colours (linear) per part class, and the exported glow rig's (tools/export_models.mjs).
const PARTS={body:'ribcage',accent:'sternum',edge:'jaw',flex:'neck-joint'};
const lin=c=>[r6(c.r),r6(c.g),r6(c.b)];
const exported=createCharacterRig('#70e1d0','#e5e7eb',true),colorOf=(r,n)=>lin(r.group.getObjectByName(n).material.color);
const colours={exported:Object.fromEntries(Object.entries(PARTS).map(([k,n])=>[k,colorOf(exported,n)])),portrait:[]};
for(const [body,accent] of [['#e5e7eb','#70e1d0'],['#e5e7eb','#ff6b35'],['#1f2937','#ff6b35'],['#fca5a5','#69a6ff'],['#86efac','#ba94f5'],['#f4f4f5','#ffffff'],['#4b5563','#ffd27a'],['#000000','#000000']]){const r=createCharacterRig(accent,body);colours.portrait.push({bodyHex:body,accentHex:accent,...Object.fromEntries(Object.entries(PARTS).map(([k,n])=>[k,colorOf(r,n)]))});}
colours.emissive=Object.fromEntries(Object.entries(PARTS).map(([k,n])=>[k,lin(createCharacterRig('#ff6b35','#e5e7eb').group.getObjectByName(n).material.emissive)]));
// Every exported (glow) pilot part's class in the portrait rig, read from its material: distinctive body and accent colours
// make body, accent, edgeOf(body) and flexOf(body) tell apart; parts the portrait rig lacks (the armour strips) are hidden.
{const probe=createCharacterRig('#123456','#abcdef'),hex=c=>c.getHex(),body=new T.Color('#abcdef').getHex(),accent=new T.Color('#123456').getHex();const byName=new Map();probe.group.traverse(o=>{if(o.isMesh)byName.set(o.name,o);});
 const names=new Set();exported.group.traverse(o=>{if(o.isMesh)names.add(o.name);});
 const edge=hex(byName.get('jaw').material.color),flex=hex(byName.get('neck-joint').material.color);
 colours.parts=Object.fromEntries([...names].sort().map(n=>{const m=byName.get(n);if(!m)return [n,'hidden'];const c=hex(m.material.color);return [n,c===body?'body':c===accent?'accent':c===edge?'edge':c===flex?'flex':'other'];}));}
// lobbyChair() parts.
const chair=lobbyChair().children.map(m=>({name:m.name,p:arr(m.position),s:arr(m.scale),c:m.material.color.getHex()}));
// The Auditor halo: rest build and animateCosmetics at each time (group, arcs and glow tubes, flames).
const halo={times:[0,.37,1.3,2.9,7.1],frames:[]};
for(const t of halo.times){const g=auditorHalo(),head=new T.Group();head.add(g);animateCosmetics({sockets:{head}},t);
 halo.frames.push({t,group:{p:arr(g.position),q:arr(g.quaternion),s:arr(g.scale)},children:g.children.map(o=>({name:o.name||(o.material.blending===T.AdditiveBlending?'aura':'arc'),p:arr(o.position),q:arr(o.quaternion),s:arr(o.scale)}))});}
{const g=auditorHalo();const arc=g.children[0],aura=g.children[1],flame=g.children.find(o=>o.name==='auditor-flame');
 const geo=m=>({positions:[...m.geometry.getAttribute('position').array].map(r6),normals:[...m.geometry.getAttribute('normal').array].map(r6),indices:[...(m.geometry.index?.array??[])]});
 const mat=m=>({color:m.material.color.getHex(),opacity:m.material.opacity,transparent:m.material.transparent,additive:m.material.blending===T.AdditiveBlending,depthWrite:m.material.depthWrite,toneMapped:m.material.toneMapped,doubleSide:m.material.side===T.DoubleSide});
 Object.assign(halo,{arc:{...geo(arc),...mat(arc)},aura:{...geo(aura),...mat(aura)},flame:{...geo(flame),...mat(flame)}});}
// three r180 primitives as the portrait scene builds them.
const geo=g=>({positions:[...g.getAttribute('position').array].map(r6),normals:[...g.getAttribute('normal').array].map(r6),indices:[...g.index.array]});
const primitives={box:geo(new T.BoxGeometry(1,1,1)),podium:geo(new T.CylinderGeometry(.96,1.02,.075,32))};
const out={source:'05950eaef80ff2483a9c44d898cad98be1a76bbc',bones:BONES,poses:POSES,labels:POSES.map(k=>LOBBY_POSES[k]),fallback:lobbyPose('crossed-arms'),cases:poses,frames,hatTops,colours,chair,halo,primitives};
fs.writeFileSync(path.join(root,'Tests/lobby-pose-parity.json'),JSON.stringify(out));
console.log('lobby pose fixtures:',poses.length,'poses,',frames.length,'framings,',hatTops.length,'hat tops,',colours.portrait.length,'colour sets,',halo.frames.length,'halo frames');
